  const [workingState,setWorkingState]=useState<{scope:string;items:EvaluationForm[]}>(()=>({scope:workingScope,items:workingScope?readStore(workingStorage,[]):[]}))
  const workingForms=workingState.scope===workingScope?workingState.items:[]
  const setWorkingForms=(update:(current:EvaluationForm[])=>EvaluationForm[])=>setWorkingState(current=>({scope:workingScope,items:update(current.scope===workingScope?current.items:workingScope?readStore(workingStorage,[]):[])}))
  useEffect(()=>{if(workingScope)setWorkingState({scope:workingScope,items:readStore(workingStorage,[])})},[workingScope])
  useEffect(()=>{if(workingScope&&workingState.scope===workingScope)localStorage.setItem(workingStorage,JSON.stringify(workingState.items))},[workingScope,workingState])
