    if(!connected){setLocalForms(next);return}
    setWorkingForms(current=>[...current.filter(item=>!next.some(form=>form.id===item.id&&serverForms.some(saved=>saved.id===item.id&&['DRAFT','TESTING'].includes(formStatus(saved))))),...next.filter(item=>serverForms.some(saved=>saved.id===item.id)&&!sameDefinition(serverForms.find(saved=>saved.id===item.id)!,item))])
