  const unsavedForms=connected?[...workingForms,...localForms.filter(item=>!serverForms.some(saved=>saved.id===item.id)&&(dirtyLocalFormIds.current.has(item.id)||selectedFormId===item.id)&&['DRAFT','TESTING'].includes(formStatus(item)))]:[]
  const canLeavePage=(next:Page)=>{if(page==='answerSets'&&next!=='answerSets'&&answerSetDirty!==null&&!window.confirm(`You have unsaved changes to ${answerSetDirty}. Leave this Answer Set and discard them?`))return false;if(page==='groups'&&next!=='groups'&&groupDirty!==null&&!window.confirm(`You have unsaved changes to ${groupDirty}. Leave this group and discard them?`))return false;if(page==='settings'&&next!=='settings'&&settingsDirty&&!window.confirm('You have unsaved Settings changes. Leave without saving them?'))return false;if(page==='policies'&&next!=='policies'&&policyDirty&&!window.confirm('Unsaved policy or schedule changes. Leave without saving?'))return false;if(page==='forms'&&next!=='forms'&&unsavedForms.length&&!window.confirm('Unsaved changes remain in this browser. Leave without saving to the server?'))return false;return true}
  // Cross-workspace investigations commit their already constructed URL once.
